      WHERE e.extname='postgis' AND n.nspname='public') OR NOT EXISTS (
      SELECT 1 FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace
      WHERE e.extname='pgcrypto' AND n.nspname='extensions') THEN
    RAISE EXCEPTION 'Expected existing public PostGIS and extensions pgcrypto; do not move extensions';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace='public'::regnamespace
      AND left(p.proname,7)='nearby_') THEN
    RAISE EXCEPTION 'New RPC already exists; stop on repeat application or drift';
  END IF;
END $environment$;
DO $fk_name$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE
    conrelid='safe_walk_nearby.alert_deliveries'::regclass
    AND conname='alert_deliveries_recipient_id_fkey' AND contype='f') THEN
    RAISE EXCEPTION 'Unexpected recipient FK name; stop and review';
  END IF;
END $fk_name$;
ALTER TABLE safe_walk_nearby.helper_profiles ADD CONSTRAINT helper_profiles_consent_version_check
  CHECK (char_length(consent_version) BETWEEN 1 AND 64);
-- Change only the inventoried recipient FK. Existing rows are validated, never deleted.
ALTER TABLE safe_walk_nearby.alert_deliveries
  DROP CONSTRAINT alert_deliveries_recipient_id_fkey;
ALTER TABLE safe_walk_nearby.alert_deliveries ADD CONSTRAINT alert_deliveries_recipient_id_fkey
  FOREIGN KEY (recipient_id) REFERENCES auth.users(id) ON DELETE CASCADE;
-- ---------------------------------------------------------------- tables

create table if not exists safe_walk_nearby.helper_profiles (
  user_id uuid primary key references auth.users (id) on delete cascade,
  consent_version text not null check (char_length(consent_version) between 1 and 64),
  consented_at timestamptz not null,
  revoked_at timestamptz
);

-- At most one row per helper: the latest position only, never a history.
create table if not exists safe_walk_nearby.helper_locations (
  user_id uuid primary key
    references safe_walk_nearby.helper_profiles (user_id) on delete cascade,
  geog public.geography (point, 4326) not null,
  accuracy_m real check (accuracy_m is null or accuracy_m >= 0),
  reported_at timestamptz not null,
  expires_at timestamptz not null
);
create index if not exists helper_locations_expires_idx
  on safe_walk_nearby.helper_locations (expires_at);

create table if not exists safe_walk_nearby.alerts (
  id uuid primary key default gen_random_uuid(),
  sender_id uuid not null references auth.users (id) on delete cascade,
  client_request_id uuid not null,
  geog public.geography (point, 4326) not null,
  radius_m integer not null default 500 check (radius_m = 500),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  unique (sender_id, client_request_id)
);
create index if not exists alerts_sender_created_idx
  on safe_walk_nearby.alerts (sender_id, created_at desc);
create index if not exists alerts_expires_idx
  on safe_walk_nearby.alerts (expires_at);

create table if not exists safe_walk_nearby.alert_deliveries (
  alert_id uuid not null
    references safe_walk_nearby.alerts (id) on delete cascade,
  recipient_id uuid not null
    references auth.users (id) on delete cascade,
  delivered_at timestamptz not null default now(),
  seen_at timestamptz,
  primary key (alert_id, recipient_id)
);
create index if not exists alert_deliveries_recipient_idx
  on safe_walk_nearby.alert_deliveries (recipient_id);

-- Guard areas: places a helper asks to be notified about even when their live
-- position is unknown or expired. The centre is stored rounded to 3 decimals
-- (about 100 m), at most 3 per helper. The server cannot verify that a centre is
-- somewhere the helper really is; see docs/SAFE_WALK_NEARBY_HELPER_DESIGN.md.
create table if not exists safe_walk_nearby.helper_areas (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null
    references safe_walk_nearby.helper_profiles (user_id) on delete cascade,
  center public.geography (point, 4326) not null,
  radius_m integer not null check (radius_m between 500 and 1000),
  created_at timestamptz not null default now()
);
create index if not exists helper_areas_center_idx
  on safe_walk_nearby.helper_areas using gist (center);
create index if not exists helper_areas_user_idx
  on safe_walk_nearby.helper_areas (user_id);

-- Trusted contacts: people a person has paired with an invite code. When that
-- person sends an SOS, their contacts are notified in the app whatever the
-- distance, and see the name the person chose. The code is only ever stored as a
-- hash. Neither side learns the other's identity beyond that name.
create table if not exists safe_walk_nearby.contact_invites (
  code_hash text primary key,
  owner_id uuid not null references auth.users (id) on delete cascade,
  display_name text not null check (char_length(display_name) between 1 and 20),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null
);
create index if not exists contact_invites_owner_idx
  on safe_walk_nearby.contact_invites (owner_id);

create table if not exists safe_walk_nearby.trusted_contacts (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  contact_id uuid not null references auth.users (id) on delete cascade,
  display_name text not null check (char_length(display_name) between 1 and 20),
  created_at timestamptz not null default now(),
  unique (owner_id, contact_id),
  check (owner_id <> contact_id)
);
create index if not exists trusted_contacts_owner_idx
  on safe_walk_nearby.trusted_contacts (owner_id);
create index if not exists trusted_contacts_contact_idx
  on safe_walk_nearby.trusted_contacts (contact_id);

-- Every attempt to use a code, so guessing can be throttled. (A failed attempt
-- must not raise: the exception would roll the record back.)
create table if not exists safe_walk_nearby.contact_invite_attempts (
  user_id uuid not null references auth.users (id) on delete cascade,
  attempted_at timestamptz not null default now()
);
create index if not exists contact_invite_attempts_idx
  on safe_walk_nearby.contact_invite_attempts (user_id, attempted_at);

alter table safe_walk_nearby.helper_profiles enable row level security;
alter table safe_walk_nearby.helper_locations enable row level security;
alter table safe_walk_nearby.alerts enable row level security;
alter table safe_walk_nearby.alert_deliveries enable row level security;
alter table safe_walk_nearby.helper_areas enable row level security;
alter table safe_walk_nearby.contact_invites enable row level security;
alter table safe_walk_nearby.trusted_contacts enable row level security;
alter table safe_walk_nearby.contact_invite_attempts enable row level security;
-- Deliberately no policies: deny by default. Only the SECURITY DEFINER
-- functions below (owned by the migration owner) touch these tables.

revoke all on schema safe_walk_nearby from public;
revoke all on all tables in schema safe_walk_nearby from public;
alter default privileges in schema safe_walk_nearby revoke all on tables from public;

do $revoke_api_roles$
declare
  api_role text;
begin
  foreach api_role in array array['anon', 'authenticated', 'service_role'] loop
    if exists (select 1 from pg_catalog.pg_roles where rolname = api_role) then
      execute format('revoke all on schema safe_walk_nearby from %I', api_role);
      execute format(
        'revoke all on all tables in schema safe_walk_nearby from %I', api_role
      );
    end if;
  end loop;
end
$revoke_api_roles$;

-- ------------------------------------------------------------- functions
-- Error codes map to HTTP through PostgREST: 28000 -> 403, 42501 -> 401/403,
-- 22023 -> 400, PT429 -> 429.

create or replace function public.nearby_helper_opt_in(p_consent_version text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('safe_walk_nearby:user:' || v_uid::text, 0));
  if p_consent_version is null
     or char_length(p_consent_version) not between 1 and 64 then
    raise exception 'invalid_input' using errcode = '22023';
  end if;
  -- Repeating this call while already joined (the app refreshes a helper's
  -- position this way) keeps the original consent time; a new consent version or
  -- rejoining after opting out records a new one.
  insert into safe_walk_nearby.helper_profiles as hp
    (user_id, consent_version, consented_at, revoked_at)
  values (v_uid, p_consent_version, now(), null)
  on conflict (user_id) do update
    set consented_at = case
          when hp.revoked_at is null
               and hp.consent_version = excluded.consent_version
            then hp.consented_at
          else excluded.consented_at
        end,
        consent_version = excluded.consent_version,
        revoked_at = null;
end;
$$;

-- Withdrawing consent deletes the stored position immediately.
create or replace function public.nearby_helper_opt_out()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('safe_walk_nearby:user:' || v_uid::text, 0));
  delete from safe_walk_nearby.helper_locations where user_id = v_uid;
  delete from safe_walk_nearby.helper_areas where user_id = v_uid;
  update safe_walk_nearby.helper_profiles
    set revoked_at = now()
    where user_id = v_uid and revoked_at is null;
end;
$$;

create or replace function public.nearby_helper_report_location(
  p_lat double precision,
  p_lng double precision,
  p_accuracy_m real default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_last timestamptz;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('safe_walk_nearby:user:' || v_uid::text, 0));
  if p_lat is null or p_lng is null
     or p_lat <> p_lat or p_lng <> p_lng
     or p_lat not between -90 and 90 or p_lng not between -180 and 180
     or (p_accuracy_m is not null
         and (p_accuracy_m <> p_accuracy_m or p_accuracy_m < 0
              or p_accuracy_m > 500)) then
    raise exception 'invalid_input' using errcode = '22023';
  end if;
  if not exists (
    select 1 from safe_walk_nearby.helper_profiles
    where user_id = v_uid and revoked_at is null
  ) then
    raise exception 'not_a_helper' using errcode = '42501';
  end if;
  select reported_at into v_last
    from safe_walk_nearby.helper_locations where user_id = v_uid;
  if v_last is not null and v_last > now() - interval '10 seconds' then
    raise exception 'rate_limited' using errcode = 'PT429';
  end if;
  insert into safe_walk_nearby.helper_locations
    (user_id, geog, accuracy_m, reported_at, expires_at)
  values (
    v_uid,
    public.st_setsrid(public.st_makepoint(p_lng, p_lat), 4326)::public.geography,
    p_accuracy_m,
    now(),
    now() + interval '10 minutes'
  )
  on conflict (user_id) do update
    set geog = excluded.geog,
        accuracy_m = excluded.accuracy_m,
        reported_at = excluded.reported_at,
        expires_at = excluded.expires_at;
end;
$$;

-- Returns only the number of helpers notified. It never returns identities or
-- coordinates of other people.
create or replace function public.nearby_sos_send(
  p_lat double precision,
  p_lng double precision,
  p_client_request_id uuid
)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_alert_id uuid;
  v_geog public.geography;
  v_count integer;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('safe_walk_nearby:user:' || v_uid::text, 0));
  if p_lat is null or p_lng is null or p_client_request_id is null
     or p_lat <> p_lat or p_lng <> p_lng
     or p_lat not between -90 and 90 or p_lng not between -180 and 180 then
    raise exception 'invalid_input' using errcode = '22023';
  end if;

  -- A retry of the same request returns the original result and notifies no one.
  select id into v_alert_id
    from safe_walk_nearby.alerts
    where sender_id = v_uid and client_request_id = p_client_request_id;
  if v_alert_id is not null then
    select count(*)::integer into v_count
      from safe_walk_nearby.alert_deliveries where alert_id = v_alert_id;
    return v_count;
  end if;

  if exists (
    select 1 from safe_walk_nearby.alerts
    where sender_id = v_uid and created_at > now() - interval '15 seconds'
  ) or (
    select count(*) from safe_walk_nearby.alerts
    where sender_id = v_uid and created_at > now() - interval '1 hour'
  ) >= 5 then
    raise exception 'rate_limited' using errcode = 'PT429';
  end if;

  v_geog := public.st_setsrid(
    public.st_makepoint(p_lng, p_lat), 4326
  )::public.geography;

  insert into safe_walk_nearby.alerts
    (sender_id, client_request_id, geog, radius_m, expires_at)
  values (v_uid, p_client_request_id, v_geog, 500, now() + interval '30 minutes')
  on conflict (sender_id, client_request_id) do nothing
  returning id into v_alert_id;
  if v_alert_id is null then
    select id into v_alert_id
      from safe_walk_nearby.alerts
      where sender_id = v_uid and client_request_id = p_client_request_id;
    select count(*)::integer into v_count
      from safe_walk_nearby.alert_deliveries where alert_id = v_alert_id;
    return v_count;
  end if;

  -- A helper is notified when their fresh live position is within 500 m, or
  -- when one of their guard areas covers the SOS position. Each helper once.
  insert into safe_walk_nearby.alert_deliveries (alert_id, recipient_id)
  select v_alert_id, nearest.user_id
  from (
    select c.user_id, min(c.dist) as dist
    from (
      select hl.user_id,
             public.st_distance(hl.geog, v_geog) as dist
      from safe_walk_nearby.helper_locations hl
      join safe_walk_nearby.helper_profiles hp on hp.user_id = hl.user_id
      where hp.revoked_at is null
        and hl.expires_at > now()
        and public.st_dwithin(hl.geog, v_geog, 500)
      union all
      select ha.user_id,
             public.st_distance(ha.center, v_geog) as dist
      from safe_walk_nearby.helper_areas ha
      join safe_walk_nearby.helper_profiles hp on hp.user_id = ha.user_id
      where hp.revoked_at is null
        and public.st_dwithin(ha.center, v_geog, ha.radius_m)
    ) c
    where c.user_id <> v_uid
    group by c.user_id
    order by min(c.dist)
    limit 50
  ) as nearest;

  -- The sender's trusted contacts, whatever the distance. They do not count
  -- against the 50 helper limit (a person has at most 5 contacts).
  insert into safe_walk_nearby.alert_deliveries (alert_id, recipient_id)
  select v_alert_id, tc.contact_id
  from safe_walk_nearby.trusted_contacts tc
  where tc.owner_id = v_uid
  on conflict (alert_id, recipient_id) do nothing;

  select count(*)::integer into v_count
    from safe_walk_nearby.alert_deliveries where alert_id = v_alert_id;
  return v_count;
end;
$$;

-- Alerts addressed to the caller that are still valid, for an active helper or a
-- trusted contact. A helper never learns who sent one. A trusted contact sees the
-- name the sender chose for them (from_contact, sender_name). Calls may repeat
-- results; clients de-duplicate by alert_id so a crash after fetching cannot lose
-- an SOS.
create or replace function public.nearby_helper_fetch_alerts()
returns table (
  alert_id uuid,
  lat double precision,
  lng double precision,
  radius_m integer,
  created_at timestamptz,
  expires_at timestamptz,
  from_contact boolean,
  sender_name text
)
language plpgsql
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  if not exists (
       select 1 from safe_walk_nearby.helper_profiles
       where user_id = v_uid and revoked_at is null
     )
     and not exists (
       select 1 from safe_walk_nearby.trusted_contacts
       where contact_id = v_uid
     ) then
    raise exception 'not_a_helper' using errcode = '42501';
  end if;
  return query
  with touched as (
    update safe_walk_nearby.alert_deliveries d
      set seen_at = coalesce(d.seen_at, now())
      from safe_walk_nearby.alerts a
      where d.alert_id = a.id
        and d.recipient_id = v_uid
        and a.expires_at > now()
      returning a.id, a.geog, a.radius_m, a.created_at, a.expires_at, a.sender_id
  )
  select t.id,
         public.st_y(t.geog::public.geometry),
         public.st_x(t.geog::public.geometry),
         t.radius_m, t.created_at, t.expires_at,
         tc.id is not null,
         tc.display_name
  from touched t
  left join safe_walk_nearby.trusted_contacts tc
    on tc.owner_id = t.sender_id and tc.contact_id = v_uid
  order by t.created_at desc;
end;
$$;

-- Replaces the caller's guard areas (at most 3). Centres are rounded to about
-- 100 m here, whatever the client sent.
create or replace function public.nearby_helper_set_areas(p_areas jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_item jsonb;
  v_lat numeric;
  v_lng numeric;
  v_radius numeric;
  v_last timestamptz;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('safe_walk_nearby:user:' || v_uid::text, 0));
  if p_areas is null or jsonb_typeof(p_areas) <> 'array'
     or jsonb_array_length(p_areas) > 3 then
    raise exception 'invalid_input' using errcode = '22023';
  end if;
  if not exists (
    select 1 from safe_walk_nearby.helper_profiles
    where user_id = v_uid and revoked_at is null
  ) then
    raise exception 'not_a_helper' using errcode = '42501';
  end if;
  select max(created_at) into v_last
    from safe_walk_nearby.helper_areas where user_id = v_uid;
  if v_last is not null and v_last > now() - interval '10 seconds' then
    raise exception 'rate_limited' using errcode = 'PT429';
  end if;

  -- Validate everything before changing anything.
  for v_item in select value from jsonb_array_elements(p_areas) loop
    if jsonb_typeof(v_item) <> 'object'
       or jsonb_typeof(v_item -> 'lat') is distinct from 'number'
       or jsonb_typeof(v_item -> 'lng') is distinct from 'number'
       or jsonb_typeof(v_item -> 'radius_m') is distinct from 'number' then
      raise exception 'invalid_input' using errcode = '22023';
    end if;
    v_lat := (v_item ->> 'lat')::numeric;
    v_lng := (v_item ->> 'lng')::numeric;
    v_radius := (v_item ->> 'radius_m')::numeric;
    if v_lat not between -90 and 90 or v_lng not between -180 and 180
       or v_radius <> trunc(v_radius) or v_radius not between 500 and 1000 then
      raise exception 'invalid_input' using errcode = '22023';
    end if;
  end loop;

  delete from safe_walk_nearby.helper_areas where user_id = v_uid;
  insert into safe_walk_nearby.helper_areas (user_id, center, radius_m)
  select v_uid,
         public.st_setsrid(
           public.st_makepoint(
             round((e ->> 'lng')::numeric, 3)::double precision,
             round((e ->> 'lat')::numeric, 3)::double precision),
           4326)::public.geography,
         (e ->> 'radius_m')::integer
  from jsonb_array_elements(p_areas) as e;
end;
$$;

-- The caller's own guard areas, as stored (already rounded).
create or replace function public.nearby_helper_get_areas()
returns table (lat double precision, lng double precision, radius_m integer)
language plpgsql
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  if not exists (
    select 1 from safe_walk_nearby.helper_profiles
    where user_id = v_uid and revoked_at is null
  ) then
    raise exception 'not_a_helper' using errcode = '42501';
  end if;
  return query
  select public.st_y(ha.center::public.geometry),
         public.st_x(ha.center::public.geometry),
         ha.radius_m
  from safe_walk_nearby.helper_areas ha
  where ha.user_id = v_uid
  order by ha.created_at, ha.id;
end;
$$;

-- Creates a one-time invite code (24 h) for pairing a trusted contact. The code
-- is returned once and stored only as a hash. [p_display_name] is how this
-- person will appear to the contact.
create or replace function public.nearby_contact_invite_create(p_display_name text)
returns table (code text, expires_at timestamptz)
language plpgsql
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  v_uid uuid := auth.uid();
  v_name text;
  v_code text := '';
  v_expires timestamptz := now() + interval '24 hours';
  v_last timestamptz;
  i integer;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('safe_walk_nearby:contacts', 0));
  perform pg_advisory_xact_lock(hashtextextended('safe_walk_nearby:user:' || v_uid::text, 0));
  v_name := btrim(coalesce(p_display_name, ''));
  if char_length(v_name) not between 1 and 20 then
    raise exception 'invalid_input' using errcode = '22023';
  end if;
  delete from safe_walk_nearby.contact_invites ci
    where ci.owner_id = v_uid and ci.expires_at <= now();
  select max(ci.created_at) into v_last
    from safe_walk_nearby.contact_invites ci where ci.owner_id = v_uid;
  if v_last is not null and v_last > now() - interval '5 seconds' then
    raise exception 'rate_limited' using errcode = 'PT429';
  end if;
  if (select count(*) from safe_walk_nearby.contact_invites ci
        where ci.owner_id = v_uid) >= 3 then
    raise exception 'too_many_invites' using errcode = 'PT429';
  end if;
  if (select count(*) from safe_walk_nearby.trusted_contacts tc
        where tc.owner_id = v_uid) >= 5 then
    raise exception 'contact_limit' using errcode = 'PT409';
  end if;
  -- 8 characters from 31 unambiguous ones (no I, L, O, 0, 1).
  for i in 1..8 loop
    v_code := v_code || substr(
      'ABCDEFGHJKMNPQRSTUVWXYZ23456789',
      (get_byte(extensions.gen_random_bytes(1), 0) % 31) + 1, 1);
  end loop;
  insert into safe_walk_nearby.contact_invites
    (code_hash, owner_id, display_name, expires_at)
  values (encode(extensions.digest(v_code, 'sha256'), 'hex'),
          v_uid, v_name, v_expires);
  return query select v_code, v_expires;
end;
$$;

-- Uses a code to become someone's trusted contact. Returns a status instead of
-- raising on a bad code, so every attempt stays recorded and guessing is
-- throttled (10 attempts an hour): 'ok', 'invalid' (wrong, expired or already
-- used), 'self', 'owner_full' (they already have 5 contacts) or 'following_full'
-- (this person already follows 20).
create or replace function public.nearby_contact_invite_accept(p_code text)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_code text;
  v_hash text;
  v_invite record;
  v_paired boolean;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('safe_walk_nearby:contacts', 0));
  perform pg_advisory_xact_lock(hashtextextended('safe_walk_nearby:user:' || v_uid::text, 0));
  if (select count(*) from safe_walk_nearby.contact_invite_attempts a
        where a.user_id = v_uid
          and a.attempted_at > now() - interval '1 hour') >= 10 then
    raise exception 'rate_limited' using errcode = 'PT429';
  end if;
  insert into safe_walk_nearby.contact_invite_attempts (user_id) values (v_uid);

  v_code := upper(regexp_replace(coalesce(p_code, ''), '[\s-]', '', 'g'));
  if v_code !~ '^[A-HJKMNP-Z2-9]{8}$' then
    return 'invalid';
  end if;
  v_hash := encode(extensions.digest(v_code, 'sha256'), 'hex');
  select * into v_invite from safe_walk_nearby.contact_invites ci
    where ci.code_hash = v_hash and ci.expires_at > now();
  if not found then
    return 'invalid';
  end if;
  if v_invite.owner_id = v_uid then
    return 'self';
  end if;
  v_paired := exists (
    select 1 from safe_walk_nearby.trusted_contacts tc
    where tc.owner_id = v_invite.owner_id and tc.contact_id = v_uid);
  if not v_paired
     and (select count(*) from safe_walk_nearby.trusted_contacts tc
            where tc.owner_id = v_invite.owner_id) >= 5 then
    return 'owner_full';
  end if;
  if not v_paired
     and (select count(*) from safe_walk_nearby.trusted_contacts tc
            where tc.contact_id = v_uid) >= 20 then
    return 'following_full';
  end if;
  insert into safe_walk_nearby.trusted_contacts (owner_id, contact_id, display_name)
  values (v_invite.owner_id, v_uid, v_invite.display_name)
  on conflict (owner_id, contact_id) do update
    set display_name = excluded.display_name;
  delete from safe_walk_nearby.contact_invites ci where ci.code_hash = v_hash;
  return 'ok';
end;
$$;

-- The caller's own trusted contacts: only link ids and dates, never who they are.
create or replace function public.nearby_contact_list_mine()
returns table (link_id uuid, since timestamptz)
language plpgsql
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  return query
  select tc.id, tc.created_at
  from safe_walk_nearby.trusted_contacts tc
  where tc.owner_id = v_uid
  order by tc.created_at, tc.id;
end;
$$;

-- Removes one of the caller's own contacts. Someone else's link is untouched.
create or replace function public.nearby_contact_remove(p_link_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('safe_walk_nearby:contacts', 0));
  perform pg_advisory_xact_lock(hashtextextended('safe_walk_nearby:user:' || v_uid::text, 0));
  delete from safe_walk_nearby.trusted_contacts tc
    where tc.id = p_link_id and tc.owner_id = v_uid;
end;
$$;

-- The people the caller is a trusted contact of, by the name they chose.
create or replace function public.nearby_contact_following()
returns table (link_id uuid, display_name text, since timestamptz)
language plpgsql
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  return query
  select tc.id, tc.display_name, tc.created_at
  from safe_walk_nearby.trusted_contacts tc
  where tc.contact_id = v_uid
  order by tc.created_at, tc.id;
end;
$$;

-- The caller stops being someone's trusted contact.
create or replace function public.nearby_contact_unfollow(p_link_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('safe_walk_nearby:contacts', 0));
  perform pg_advisory_xact_lock(hashtextextended('safe_walk_nearby:user:' || v_uid::text, 0));
  delete from safe_walk_nearby.trusted_contacts tc
    where tc.id = p_link_id and tc.contact_id = v_uid;
end;
$$;

-- Hygiene only: every read already filters on expiry. Not exposed to API roles;
-- schedule it manually (for example with pg_cron) after review.
create or replace function safe_walk_nearby.purge_expired()
returns void
language sql
security definer
set search_path = ''
as $$
  delete from safe_walk_nearby.helper_locations where expires_at <= now();
  delete from safe_walk_nearby.alerts where expires_at <= now() - interval '1 hour';
  delete from safe_walk_nearby.contact_invites where expires_at <= now();
  delete from safe_walk_nearby.contact_invite_attempts
    where attempted_at <= now() - interval '1 day';
$$;

-- ---------------------------------------------------------------- grants

do $grants$
declare
  fn regprocedure;
  api_role text;
begin
  foreach fn in array array[
    'public.nearby_helper_opt_in(text)'::regprocedure,
    'public.nearby_helper_opt_out()'::regprocedure,
    'public.nearby_helper_report_location(double precision,double precision,real)'::regprocedure,
    'public.nearby_sos_send(double precision,double precision,uuid)'::regprocedure,
    'public.nearby_helper_fetch_alerts()'::regprocedure,
    'public.nearby_helper_set_areas(jsonb)'::regprocedure,
    'public.nearby_helper_get_areas()'::regprocedure,
    'public.nearby_contact_invite_create(text)'::regprocedure,
    'public.nearby_contact_invite_accept(text)'::regprocedure,
    'public.nearby_contact_list_mine()'::regprocedure,
    'public.nearby_contact_remove(uuid)'::regprocedure,
    'public.nearby_contact_following()'::regprocedure,
    'public.nearby_contact_unfollow(uuid)'::regprocedure,
    'safe_walk_nearby.purge_expired()'::regprocedure
  ] loop
    execute format('revoke all on function %s from public', fn);
    foreach api_role in array array['anon', 'authenticated', 'service_role'] loop
      if exists (select 1 from pg_catalog.pg_roles where rolname = api_role) then
        execute format('revoke all on function %s from %I', fn, api_role);
      end if;
    end loop;
  end loop;

  if exists (select 1 from pg_catalog.pg_roles where rolname = 'authenticated') then
    grant execute on function public.nearby_helper_opt_in(text) to authenticated;
    grant execute on function public.nearby_helper_opt_out() to authenticated;
    grant execute on function
      public.nearby_helper_report_location(double precision, double precision, real)
      to authenticated;
    grant execute on function
      public.nearby_sos_send(double precision, double precision, uuid)
      to authenticated;
    grant execute on function public.nearby_helper_fetch_alerts() to authenticated;
    grant execute on function public.nearby_helper_set_areas(jsonb) to authenticated;
    grant execute on function public.nearby_helper_get_areas() to authenticated;
    grant execute on function public.nearby_contact_invite_create(text) to authenticated;
    grant execute on function public.nearby_contact_invite_accept(text) to authenticated;
    grant execute on function public.nearby_contact_list_mine() to authenticated;
    grant execute on function public.nearby_contact_remove(uuid) to authenticated;
    grant execute on function public.nearby_contact_following() to authenticated;
    grant execute on function public.nearby_contact_unfollow(uuid) to authenticated;
  end if;
end
$grants$;


DO $verify$
DECLARE
  target_schema oid := to_regnamespace('safe_walk_nearby');
  postgis_schema text;
  geography_type oid;
  expected record;
  actual record;
  api_role text;
  relation record;
  normalized_check text;
BEGIN
  IF target_schema IS NULL THEN
    RAISE EXCEPTION 'safe_walk_nearby does not exist';
  END IF;
  SELECT n.nspname INTO STRICT postgis_schema
  FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace
  WHERE e.extname = 'postgis';
  geography_type := to_regtype(format('%I.geography', postgis_schema));

  IF (SELECT count(*) FROM pg_class
      WHERE relnamespace = target_schema AND relkind = 'r') <> 8
      OR EXISTS (SELECT 1 FROM pg_class WHERE relnamespace = target_schema
                 AND relkind NOT IN ('r', 'i'))
      OR (SELECT count(*) FROM pg_proc WHERE pronamespace = target_schema) <> 1
      OR to_regprocedure('safe_walk_nearby.purge_expired()') IS NULL
      OR EXISTS (SELECT 1 FROM pg_policy p JOIN pg_class c ON c.oid = p.polrelid
                 WHERE c.relnamespace = target_schema)
      OR EXISTS (SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid
                 WHERE c.relnamespace = target_schema AND NOT t.tgisinternal) THEN
    RAISE EXCEPTION 'Expected eight ordinary tables, indexes, one private function, zero policies/user triggers';
  END IF;

  IF (SELECT count(*) FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid
      WHERE c.relnamespace = target_schema AND c.relkind = 'r'
        AND a.attnum > 0 AND NOT a.attisdropped) <> 37 THEN
    RAISE EXCEPTION 'Expected exactly the 37 backend columns';
  END IF;
  FOR expected IN SELECT * FROM (VALUES
    ('helper_areas', 'id', 'uuid', true, 'gen_random_uuid()'),
    ('helper_areas', 'user_id', 'uuid', true, NULL),
    ('helper_areas', 'center', 'geography', true, NULL),
    ('helper_areas', 'radius_m', 'integer', true, NULL),
    ('helper_areas', 'created_at', 'timestamptz', true, 'now()'),
    ('contact_invites', 'code_hash', 'text', true, NULL),
    ('contact_invites', 'owner_id', 'uuid', true, NULL),
    ('contact_invites', 'display_name', 'text', true, NULL),
    ('contact_invites', 'created_at', 'timestamptz', true, 'now()'),
    ('contact_invites', 'expires_at', 'timestamptz', true, NULL),
    ('trusted_contacts', 'id', 'uuid', true, 'gen_random_uuid()'),
    ('trusted_contacts', 'owner_id', 'uuid', true, NULL),
    ('trusted_contacts', 'contact_id', 'uuid', true, NULL),
    ('trusted_contacts', 'display_name', 'text', true, NULL),
    ('trusted_contacts', 'created_at', 'timestamptz', true, 'now()'),
    ('contact_invite_attempts', 'user_id', 'uuid', true, NULL),
    ('contact_invite_attempts', 'attempted_at', 'timestamptz', true, 'now()'),
    ('helper_profiles', 'user_id', 'uuid', true, NULL::text),
    ('helper_profiles', 'consent_version', 'text', true, NULL),
    ('helper_profiles', 'consented_at', 'timestamptz', true, NULL),
    ('helper_profiles', 'revoked_at', 'timestamptz', false, NULL),
    ('helper_locations', 'user_id', 'uuid', true, NULL),
    ('helper_locations', 'geog', 'geography', true, NULL),
    ('helper_locations', 'accuracy_m', 'real', false, NULL),
    ('helper_locations', 'reported_at', 'timestamptz', true, NULL),
    ('helper_locations', 'expires_at', 'timestamptz', true, NULL),
    ('alerts', 'id', 'uuid', true, 'gen_random_uuid()'),
    ('alerts', 'sender_id', 'uuid', true, NULL),
    ('alerts', 'client_request_id', 'uuid', true, NULL),
    ('alerts', 'geog', 'geography', true, NULL),
    ('alerts', 'radius_m', 'integer', true, '500'),
    ('alerts', 'created_at', 'timestamptz', true, 'now()'),
    ('alerts', 'expires_at', 'timestamptz', true, NULL),
    ('alert_deliveries', 'alert_id', 'uuid', true, NULL),
    ('alert_deliveries', 'recipient_id', 'uuid', true, NULL),
    ('alert_deliveries', 'delivered_at', 'timestamptz', true, 'now()'),
    ('alert_deliveries', 'seen_at', 'timestamptz', false, NULL)
  ) AS columns(table_name, column_name, type_name, required, default_expression)
  LOOP
    SELECT a.atttypid, a.atttypmod, a.attnotnull,
      pg_get_expr(d.adbin, d.adrelid) AS default_expression
    INTO actual FROM pg_attribute a
    LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
    WHERE a.attrelid = to_regclass(format('safe_walk_nearby.%I', expected.table_name))
      AND a.attname = expected.column_name AND a.attnum > 0 AND NOT a.attisdropped;
    IF NOT FOUND OR actual.attnotnull IS DISTINCT FROM expected.required
        OR actual.default_expression IS DISTINCT FROM expected.default_expression THEN
      RAISE EXCEPTION 'Missing column or nullability/default mismatch: %.%',
        expected.table_name, expected.column_name;
    END IF;
    IF expected.type_name = 'geography' THEN
      IF actual.atttypid IS DISTINCT FROM geography_type OR
          format_type(actual.atttypid, actual.atttypmod)
            IS DISTINCT FROM format('%I.geography(Point,4326)', postgis_schema) THEN
        RAISE EXCEPTION 'Expected installed PostGIS geography(Point,4326): %.%',
          expected.table_name, expected.column_name;
      END IF;
    ELSIF actual.atttypid IS DISTINCT FROM to_regtype(expected.type_name)
        OR actual.atttypmod <> -1 THEN
      RAISE EXCEPTION 'Column type mismatch: %.%', expected.table_name, expected.column_name;
    END IF;
  END LOOP;

  -- Verify the exact PK/UNIQUE keys through their ordered column names.
  FOR expected IN SELECT * FROM (VALUES
    ('helper_areas', 'p', ARRAY['id']),
    ('contact_invites', 'p', ARRAY['code_hash']),
    ('trusted_contacts', 'p', ARRAY['id']),
    ('trusted_contacts', 'u', ARRAY['owner_id', 'contact_id']),
    ('helper_profiles', 'p', ARRAY['user_id']),
    ('helper_locations', 'p', ARRAY['user_id']),
    ('alerts', 'p', ARRAY['id']),
    ('alerts', 'u', ARRAY['sender_id', 'client_request_id']),
    ('alert_deliveries', 'p', ARRAY['alert_id', 'recipient_id'])
  ) AS keys(table_name, kind, column_names)
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM pg_constraint c
      WHERE c.conrelid = to_regclass(format('safe_walk_nearby.%I', expected.table_name))
        AND c.contype::text = expected.kind AND c.convalidated
        AND NOT c.condeferrable
        AND (SELECT array_agg(a.attname::text ORDER BY k.position)
             FROM unnest(c.conkey) WITH ORDINALITY AS k(attribute_number, position)
             JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attribute_number)
          = expected.column_names
    ) THEN
      RAISE EXCEPTION 'Missing design PK/UNIQUE: % %', expected.table_name, expected.column_names;
    END IF;
  END LOOP;

  FOR expected IN SELECT * FROM (VALUES
    ('helper_areas', 'user_id', 'safe_walk_nearby.helper_profiles', 'user_id'),
    ('contact_invites', 'owner_id', 'auth.users', 'id'),
    ('trusted_contacts', 'owner_id', 'auth.users', 'id'),
    ('trusted_contacts', 'contact_id', 'auth.users', 'id'),
    ('contact_invite_attempts', 'user_id', 'auth.users', 'id'),
    ('helper_profiles', 'user_id', 'auth.users', 'id'),
    ('helper_locations', 'user_id', 'safe_walk_nearby.helper_profiles', 'user_id'),
    ('alerts', 'sender_id', 'auth.users', 'id'),
    ('alert_deliveries', 'alert_id', 'safe_walk_nearby.alerts', 'id'),
    ('alert_deliveries', 'recipient_id', 'auth.users', 'id')
  ) AS fks(table_name, column_name, referenced_table, referenced_column)
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM pg_constraint c
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND c.conkey = ARRAY[a.attnum]
      JOIN pg_attribute r ON r.attrelid = c.confrelid AND c.confkey = ARRAY[r.attnum]
      WHERE c.conrelid = to_regclass(format('safe_walk_nearby.%I', expected.table_name))
        AND c.contype = 'f' AND c.convalidated AND NOT c.condeferrable
        AND c.confrelid = to_regclass(expected.referenced_table)
        AND a.attname = expected.column_name AND r.attname = expected.referenced_column
        AND c.confdeltype = 'c' AND c.confupdtype = 'a' AND c.confmatchtype = 's'
    ) THEN
      RAISE EXCEPTION 'Missing validated CASCADE FK: %.%', expected.table_name, expected.column_name;
    END IF;
  END LOOP;
  IF (SELECT count(*) FROM pg_constraint c JOIN pg_class t ON t.oid = c.conrelid
      WHERE t.relnamespace = target_schema) <> 26 THEN
    RAISE EXCEPTION 'Expected exactly 7 PK, 10 FK, 2 UNIQUE and 7 CHECK constraints';
  END IF;

  -- Normalize SQL keyword case, rendering parentheses/whitespace and numeric casts.
  -- No substring match: changed operators, constants or extra clauses fail.
  FOR expected IN SELECT * FROM (VALUES
    ('helper_locations', 'accuracy_misnulloraccuracy_m>=0'), ('alerts', 'radius_m=500'),
    ('helper_profiles', 'char_lengthconsent_version>=1andchar_lengthconsent_version<=64'),
    ('helper_areas', 'radius_m>=500andradius_m<=1000'),
    ('contact_invites', 'char_lengthdisplay_name>=1andchar_lengthdisplay_name<=20')
  ) AS checks(table_name, expression)
  LOOP
    SELECT lower(regexp_replace(
      regexp_replace(pg_get_expr(c.conbin, c.conrelid),
        '::(double precision|real|integer|numeric)', '', 'g'),
      '[[:space:]()]', '', 'g'))
    INTO normalized_check FROM pg_constraint c
    WHERE c.conrelid = to_regclass(format('safe_walk_nearby.%I', expected.table_name))
      AND c.contype = 'c' AND c.convalidated;
    IF NOT FOUND OR normalized_check IS DISTINCT FROM expected.expression THEN
      RAISE EXCEPTION 'CHECK mismatch on %', expected.table_name;
    END IF;
  END LOOP;

  IF NOT EXISTS (
    SELECT 1 FROM pg_index i JOIN pg_class idx ON idx.oid = i.indexrelid
    JOIN pg_am am ON am.oid = idx.relam
    JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attname = 'geog'
    WHERE i.indrelid = 'safe_walk_nearby.helper_locations'::regclass
      AND am.amname = 'gist' AND i.indisvalid AND i.indisready
      AND i.indnkeyatts = 1 AND i.indnatts = 1 AND i.indkey[0] = a.attnum
      AND i.indpred IS NULL AND i.indexprs IS NULL
  ) THEN
    RAISE EXCEPTION 'Missing valid, unconditional single-column geog GiST index';
  END IF;

  -- PUBLIC is a pseudo-role: inspect raw ACLs as well as each real API role's
  -- effective privileges, which include grants inherited from other roles.
  IF EXISTS (SELECT 1 FROM pg_namespace n,
      LATERAL aclexplode(coalesce(n.nspacl, acldefault('n', n.nspowner))) a
      WHERE n.oid = target_schema AND a.grantee = 0)
      OR EXISTS (SELECT 1 FROM pg_class c,
      LATERAL aclexplode(coalesce(c.relacl, acldefault('r', c.relowner))) a
      WHERE c.relnamespace = target_schema AND c.relkind = 'r' AND a.grantee = 0) THEN
    RAISE EXCEPTION 'PUBLIC retains schema or table ACL';
  END IF;
  FOREACH api_role IN ARRAY ARRAY['anon', 'authenticated', 'service_role'] LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = api_role) THEN
      RAISE EXCEPTION 'Expected API role % is missing', api_role;
    END IF;
    IF has_schema_privilege(api_role, target_schema, 'USAGE') OR
        has_schema_privilege(api_role, target_schema, 'CREATE') THEN
      RAISE EXCEPTION 'API role % has effective schema access', api_role;
    END IF;
    FOR relation IN SELECT oid, relname, relrowsecurity FROM pg_class
      WHERE relnamespace = target_schema AND relkind = 'r'
    LOOP
      IF NOT relation.relrowsecurity OR EXISTS (
        SELECT 1 FROM unnest(ARRAY[
          'SELECT', 'INSERT', 'UPDATE', 'DELETE', 'TRUNCATE', 'REFERENCES', 'TRIGGER'
        ]) AS privilege_name
        WHERE has_table_privilege(api_role, relation.oid, privilege_name)
      ) OR has_any_column_privilege(api_role, relation.oid, 'SELECT')
        OR has_any_column_privilege(api_role, relation.oid, 'INSERT')
        OR has_any_column_privilege(api_role, relation.oid, 'UPDATE')
        OR has_any_column_privilege(api_role, relation.oid, 'REFERENCES') THEN
        RAISE EXCEPTION 'RLS/effective table or column ACL mismatch: % / %', api_role, relation.relname;
      END IF;
    END LOOP;
  END LOOP;
END
$verify$;

-- Generator fragment; run 04_verify_backend.sql, not this fragment on its own.
DO $backend$
DECLARE
  expected record;
  actual record;
  api_role text;
  relation record;
  expression text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace
      WHERE e.extname='postgis' AND n.nspname='public') OR NOT EXISTS (
      SELECT 1 FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace
      WHERE e.extname='pgcrypto' AND n.nspname='extensions') THEN
    RAISE EXCEPTION 'Extension schema mismatch';
  END IF;
  IF (SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace
      AND left(proname,7)='nearby_') <> 13 THEN
    RAISE EXCEPTION 'Expected exactly 13 nearby RPCs; unexpected overloads fail';
  END IF;
  FOR expected IN SELECT * FROM (VALUES
    ('public.nearby_helper_opt_in(text)', 'afc814bc8caf22f1c2056f3712b6a016', true, 'void', ARRAY['p_consent_version']::text[]),
    ('public.nearby_helper_opt_out()', 'bebce5ea4bbc34549a9cd139a5fb739f', true, 'void', ARRAY[]::text[]),
    ('public.nearby_helper_report_location(double precision,double precision,real)', '01d33371d089f7522010f7c37c225125', true, 'void', ARRAY['p_lat','p_lng','p_accuracy_m']::text[]),
    ('public.nearby_sos_send(double precision,double precision,uuid)', '0527e5ef874d9a780da3413408421d2e', true, 'integer', ARRAY['p_lat','p_lng','p_client_request_id']::text[]),
    ('public.nearby_helper_fetch_alerts()', '865b6c8bb8e0b9a9c5ffb600164af1f4', true, 'table(alert_id uuid,lat double precision,lng double precision,radius_m integer,created_at timestamptz,expires_at timestamptz,from_contact boolean,sender_name text)', ARRAY[]::text[]),
    ('public.nearby_helper_set_areas(jsonb)', '91455a3daaaec9605c663292d5181d1a', true, 'void', ARRAY['p_areas']::text[]),
    ('public.nearby_helper_get_areas()', 'f0710f2435f490a4805432979d9b4092', true, 'table(lat double precision,lng double precision,radius_m integer)', ARRAY[]::text[]),
    ('public.nearby_contact_invite_create(text)', 'ab7332c761bfad42091d64aca4a23af3', true, 'table(code text,expires_at timestamptz)', ARRAY['p_display_name']::text[]),
    ('public.nearby_contact_invite_accept(text)', 'b1f59a6bd51057ee0495fade22f66cbc', true, 'text', ARRAY['p_code']::text[]),
    ('public.nearby_contact_list_mine()', '746d6bf81ee6c1480175cc82575bed70', true, 'table(link_id uuid,since timestamptz)', ARRAY[]::text[]),
    ('public.nearby_contact_remove(uuid)', 'c185ad111eb51bce69c2c3583a3ad87d', true, 'void', ARRAY['p_link_id']::text[]),
    ('public.nearby_contact_following()', 'd23a8253d3c9bf651cbd80aa2fc00628', true, 'table(link_id uuid,display_name text,since timestamptz)', ARRAY[]::text[]),
    ('public.nearby_contact_unfollow(uuid)', '82dc472f38b4b528591de51b892f9c39', true, 'void', ARRAY['p_link_id']::text[]),
    ('safe_walk_nearby.purge_expired()', '792d3b1e0fbebbb225bd4a9ad0e6f88b', false, 'void', ARRAY[]::text[])
  ) AS functions(signature, body_md5, client_callable, result, argument_names)
  LOOP
    SELECT p.*, pg_get_function_result(p.oid) AS result,
      pg_get_userbyid(p.proowner) AS owner,
      l.lanname AS language
    INTO actual FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang
    WHERE p.oid=to_regprocedure(expected.signature);
    IF NOT FOUND OR NOT actual.prosecdef OR actual.prokind <> 'f'
        OR actual.provolatile <> 'v' OR actual.proisstrict
        OR actual.proleakproof OR actual.proparallel <> 'u'
        OR actual.proconfig IS DISTINCT FROM ARRAY['search_path=""']
        OR md5(actual.prosrc) <> expected.body_md5
        OR lower(regexp_replace(regexp_replace(replace(actual.result, 'timestamp with time zone', 'timestamptz'),
             '\s+', ' ', 'g'), '\s*([(),])\s*', '\1', 'g')) <> expected.result
        OR coalesce(actual.proargnames[1:actual.pronargs], ARRAY[]::text[]) <> expected.argument_names
        OR actual.owner <> pg_get_userbyid((SELECT nspowner FROM pg_namespace
             WHERE oid='safe_walk_nearby'::regnamespace))
        OR actual.language <> (CASE WHEN expected.client_callable THEN 'plpgsql' ELSE 'sql' END) THEN
      RAISE EXCEPTION 'RPC signature/body/security metadata mismatch: %', expected.signature;
    END IF;
    IF (actual.pronargdefaults <> CASE WHEN actual.proname='nearby_helper_report_location' THEN 1 ELSE 0 END)
        OR (actual.pronargdefaults=1 AND
            pg_get_expr(actual.proargdefaults, 0) IS DISTINCT FROM 'NULL::real') THEN
      RAISE EXCEPTION 'Unexpected RPC defaults: %', expected.signature;
    END IF;
    IF EXISTS (SELECT 1 FROM aclexplode(coalesce(actual.proacl,
        acldefault('f', actual.proowner))) a WHERE a.grantee <> actual.proowner
        AND (NOT expected.client_callable OR a.grantee <> 'authenticated'::regrole
             OR a.privilege_type <> 'EXECUTE' OR a.is_grantable)) THEN
      RAISE EXCEPTION 'Unexpected explicit function ACL: %', expected.signature;
    END IF;
    FOREACH api_role IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
      IF has_function_privilege(api_role, actual.oid, 'EXECUTE') IS DISTINCT FROM
          (expected.client_callable AND api_role='authenticated') THEN
        RAISE EXCEPTION 'Effective RPC ACL mismatch: % / %', expected.signature, api_role;
      END IF;
    END LOOP;
  END LOOP;

  IF (SELECT array_agg(lower(regexp_replace(pg_get_expr(conbin,conrelid),
          '[[:space:]()]', '', 'g')) ORDER BY lower(pg_get_expr(conbin,conrelid)))
      FROM pg_constraint WHERE conrelid='safe_walk_nearby.trusted_contacts'::regclass AND contype='c')
      IS DISTINCT FROM ARRAY['char_lengthdisplay_name>=1andchar_lengthdisplay_name<=20',
                             'owner_id<>contact_id'] THEN
    RAISE EXCEPTION 'Trusted contacts CHECK mismatch';
  END IF;
  FOR expected IN SELECT * FROM (VALUES
    ('helper_locations','geog','gist',ARRAY['geog']),
    ('helper_locations','expires','btree',ARRAY['expires_at']),
    ('alerts','sender','btree',ARRAY['sender_id','created_at']),
    ('alerts','expires','btree',ARRAY['expires_at']),
    ('alert_deliveries','recipient','btree',ARRAY['recipient_id']),
    ('helper_areas','center','gist',ARRAY['center']),
    ('helper_areas','user','btree',ARRAY['user_id']),
    ('contact_invites','owner','btree',ARRAY['owner_id']),
    ('trusted_contacts','owner','btree',ARRAY['owner_id']),
    ('trusted_contacts','contact','btree',ARRAY['contact_id']),
    ('contact_invite_attempts','attempts','btree',ARRAY['user_id','attempted_at'])
  ) AS indexes(table_name, label, method, columns)
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM pg_index i JOIN pg_class idx ON idx.oid=i.indexrelid
      JOIN pg_am am ON am.oid=idx.relam
      WHERE i.indrelid=to_regclass(format('safe_walk_nearby.%I',expected.table_name))
        AND i.indisvalid AND i.indisready AND i.indpred IS NULL AND i.indexprs IS NULL
        AND am.amname=expected.method AND i.indnkeyatts=cardinality(expected.columns)
        AND i.indnatts=i.indnkeyatts
        AND (SELECT array_agg(a.attname::text ORDER BY k.position)
          FROM unnest(i.indkey) WITH ORDINALITY k(attnum,position)
          JOIN pg_attribute a ON a.attrelid=i.indrelid AND a.attnum=k.attnum) = expected.columns
    ) THEN
      RAISE EXCEPTION 'Missing valid unconditional index: % / %', expected.table_name, expected.label;
    END IF;
  END LOOP;
  -- PUBLIC column grants can be hidden by schema denial; reject those too.
  IF EXISTS (SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid,
      LATERAL aclexplode(a.attacl) acl WHERE c.relnamespace='safe_walk_nearby'::regnamespace
      AND acl.grantee <> c.relowner) THEN
    RAISE EXCEPTION 'Unexpected non-owner column ACL';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_namespace n,
      LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a
      WHERE n.oid='safe_walk_nearby'::regnamespace AND a.grantee <> n.nspowner)
      OR EXISTS (SELECT 1 FROM pg_class c,
      LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a
      WHERE c.relnamespace='safe_walk_nearby'::regnamespace AND c.relkind='r'
      AND a.grantee <> c.relowner) THEN
    RAISE EXCEPTION 'Unexpected non-owner schema/table ACL';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_class c WHERE c.relnamespace='safe_walk_nearby'::regnamespace
      AND c.relowner <> (SELECT nspowner FROM pg_namespace WHERE oid=c.relnamespace)) THEN
    RAISE EXCEPTION 'Unexpected relation owner';
  END IF;
END $backend$;

COMMIT;
